<script lang="ts">
  import {onMount} from 'svelte';import {refreshAll} from '$app/navigation';import {command,recordName} from '#lib/client/api.ts';import {uploadOriginal} from '#lib/client/uploads.ts';import type {AppData,Row} from '#lib/client/types.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';import MappingEditor from './MappingEditor.svelte';
  let {data,entityType,entityId,importMode=false}:{data:AppData;entityType?:string;entityId?:string;importMode?:boolean}=$props();let files:FileList|undefined=$state();let busy=$state(false);let error=$state('');let uploaded:Row[]=$state([]);let kind=$state('customers');let mapping=$state('{}');let sourceName=$state('');let supplierId=$state('');let validFrom=$state('');let staged=$state(false);let fileInput:HTMLInputElement;const confirmedFiles=new Set<string>();const stagedDocIds=new Set<string>();let stagedBatches:Row[]=$state([]);
  const priceMode=$derived(data.module?.slug==='price-imports'||kind==='prices');
  const importTypes=$derived(data.module?.slug==='price-imports'?[{value:'prices',label:'Preisliste'}]:[...(data.summary?.importRowTypes||[{value:'customers',label:'Kunden'},{value:'suppliers',label:'Lieferanten'},{value:'products',label:'Artikel'},{value:'orders',label:'Aufträge'},{value:'invoices',label:'Historische Rechnungen'},{value:'payments',label:'Zahlungen / Bankdaten'},{value:'documents',label:'Dokumentenbestand'},{value:'employees',label:'Mitarbeiter'}]),...((data.summary?.importRowTypes||[]).some((type:Row)=>type.value==='prices')?[]:[{value:'prices',label:'Preisliste · mit Lieferantenfreigabe'}])]);
  onMount(()=>{if(data.module?.slug==='price-imports')kind='prices';});
  async function upload(event:SubmitEvent){event.preventDefault();if(!files?.length||busy)return;busy=true;error='';try{for(const file of Array.from(files)){const fingerprint=file.name+':'+file.size+':'+file.lastModified;if(confirmedFiles.has(fingerprint))continue;const result=await uploadOriginal(file,entityType,entityId);uploaded=[...uploaded,{...result,...(result.document||{}),original_name:file.name}];staged=false;confirmedFiles.add(fingerprint);}confirmedFiles.clear();files=undefined;if(fileInput)fileInput.value='';await refreshAll().catch(()=>{});}catch(e){error=e instanceof DOMException&&['NotReadableError','NotFoundError'].includes(e.name)?'Die ausgewählte Datei ist nicht mehr lesbar oder wurde zwischenzeitlich geändert. Wählen Sie das Original erneut aus und starten Sie den Upload noch einmal.':e instanceof Error?e.message:'Upload fehlgeschlagen.';}finally{busy=false;}}
  async function stage(event:SubmitEvent){event.preventDefault();if(busy)return;error='';let parsed:Row;try{parsed=JSON.parse(mapping);if(typeof parsed!=='object'||Array.isArray(parsed)||!parsed)throw new Error();}catch{error='Das Spaltenmapping muss ein JSON-Objekt sein, zum Beispiel {"Kundenname":"name"}.';return;}busy=true;try{for(const doc of uploaded){const documentId=doc.id||doc.document_id;if(stagedDocIds.has(documentId))continue;const result=await command(priceMode?'catalog.price_import.stage':'migration.import.stage',undefined,{document_id:documentId,kind,mapping:parsed,source_name:sourceName,...(priceMode?{supplier_id:supplierId,valid_from:validFrom}:{})});stagedDocIds.add(documentId);if(result.id)stagedBatches=[...stagedBatches,{id:result.id,name:doc.original_name,route:priceMode?'price-imports':'imports'}];}staged=true;await refreshAll().catch(()=>{});}catch(e){error=(stagedDocIds.size?`${stagedDocIds.size} Prüfcharge(n) sind bereits angelegt und werden beim erneuten Versuch übersprungen. `:'')+(e instanceof Error?e.message:'Importvorbereitung fehlgeschlagen.');}finally{busy=false;}}
</script>
<section class="panel mb"><header class="panel-header"><div><h2>{importMode?'Importdateien vorbereiten':'Dokumente aufnehmen'}</h2><p>{importMode?'Original sichern, Zuordnung prüfen, anschließend bewusst übernehmen.':'Dateien werden privat in Quarantäne gespeichert und vor der weiteren Nutzung geprüft.'}</p></div><Icon name="upload" size={18}/></header><div class="panel-body">{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}<form onsubmit={upload}><div class="upload-zone"><Icon name="upload" size={25}/><h3>{importMode?'Datei für die Importwerkbank auswählen':'Dateien oder Fotos auswählen'}</h3><p>{importMode?'CSV, XLSX, XML, PDF, Bilder oder ZIP. Keine automatische Übernahme in den Betrieb.':'Originaldatei und Dateiname bleiben erhalten. Die Dateiprüfung kann etwas Zeit benötigen.'}</p><p class="field-help">Bis zu 40 MB je Originaldatei. Größere Dateien werden direkt in den privaten Speicher übertragen und anschließend geprüft.</p><label class="sr-only" for="document-upload">Dateien auswählen</label><input id="document-upload" bind:this={fileInput!} type="file" multiple bind:files accept=".pdf,.png,.jpg,.jpeg,.webp,.csv,.xlsx,.xml,.zip,.txt,.svg,.glb,.gltf,.dxf" required/></div><div class="inline-actions mt"><button class="btn primary" type="submit" disabled={busy||!files?.length}><Icon name={busy?'refresh':'upload'} size={16} class={busy?'spin':''}/>{busy?'Wird übertragen …':'Privat hochladen'}</button><span class="small muted">{files?.length?`${files.length} Datei(en) ausgewählt`:''}</span></div></form>{#if uploaded.length}<div class="file-list" aria-live="polite">{#each uploaded as doc}<div class="file-row"><Icon name="file"/><div class="file-info"><h3>{recordName(doc)}</h3><p>Original empfangen · Weitere Verarbeitung nach Sicherheitsprüfung</p><Status value={doc.scan_status||doc.status||'quarantine'}/></div>{#if doc.id&&data.context?.permissions.includes("documents")}<a class="text-link" href={`/documents/${doc.id}`}>Dateistatus<Icon name="arrow" size={15}/></a>{/if}</div>{/each}</div>{#if importMode&&!staged}<form class="form-section" onsubmit={stage}><h3>Importauftrag</h3><div class="field-grid">{#if priceMode}<div class="field"><label for="price-supplier">Lieferant *</label><select id="price-supplier" bind:value={supplierId} required><option value="">Lieferant auswählen</option>{#each data.lookups?.suppliers||[] as supplier}<option value={supplier.id}>{supplier.name}</option>{/each}</select></div><div class="field"><label for="price-valid-from">Bestätigte Gültigkeit ab *</label><input id="price-valid-from" type="date" bind:value={validFrom} required/></div>{/if}<div class="field"><label for="import-kind">Inhalt *</label><select id="import-kind" bind:value={kind} required>{#each importTypes as type}<option value={type.value}>{type.label}</option>{/each}</select></div><div class="field"><label for="import-source">Quellsystem / Herkunft</label><input id="import-source" bind:value={sourceName} placeholder="Zum Beispiel DIESTEIN-Dateiexport"/></div><div class="field full"><span class="field-label">Spalten zuordnen</span><MappingEditor bind:value={mapping} {kind} targetFields={data.summary?.importRowFields?.[kind]}/></div></div><button class="btn mt" type="submit" disabled={busy}>Prüfcharge vorbereiten<Icon name="arrow" size={16}/></button></form>{:else if staged}<div class="notice info mt" role="status"><Icon name="check"/><div>Prüfcharge angelegt. Kontrollieren Sie Zuordnungen und Fehler in der Importliste, bevor Sie Daten übernehmen.</div></div>{/if}{#if stagedBatches.length}<div class="inline-actions mt">{#each stagedBatches as batch}<a class="btn" href={`/${batch.route}/${batch.id}`}>Prüfcharge {batch.name} öffnen<Icon name="arrow" size={15}/></a>{/each}</div>{/if}{/if}</div></section>
